<div class="d-flex justify-content-between mb-3"><h2 class="fw-bold">Nouveau bon de commande</h2><a class="btn btn-outline-dark" href="<?=e(base_url('purchases'))?>">Retour</a></div><form method="post" action="<?=e(base_url('purchases/create'))?>" class="km-card p-4"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Fournisseur</label><select class="form-select" name="supplier_id" required><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['company_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Notes</label><input class="form-control" name="notes"></div></div><hr><div id="lines"><?php for($i=0;$i<3;$i++):?><div class="row g-2 mb-2 purchase-line"><div class="col-md-6"><select class="form-select" name="product_id[]"><option value="">Produit…</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['internal_code'].' — '.$p['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" type="number" step="0.001" name="qty[]" placeholder="Qté"></div><div class="col-md-3"><input class="form-control" type="number" step="0.01" name="price[]" placeholder="Prix achat"></div></div><?php endfor;?></div><button class="btn btn-km mt-3">Créer le bon</button></form>